def cache_audit(folder,kind,paths,cache_dir,function):
    dependencies=hashes(paths);key=signature({'schema':SCHEMA,'kind':kind,'inputs':dependencies})
    cache=cache_dir/(folder.name+'_'+signature(str(folder))[:10]+'_'+kind+'_'+key+'.json')
    if cache.exists():
        value=readjson(cache)
        if value.get('signature')!=key or value.get('inputs_sha256')!=dependencies:raise ValueError('Cache receipt mismatch')
        return value['result'],{'hit':True,'file':str(cache),'signature':key}
    value=function()
    if hashes(paths)!=dependencies:raise ValueError('Audit inputs changed during read; no cache/result accepted')
    atomic(cache,{'schema':SCHEMA,'created_utc':utc(),'signature':key,'inputs_sha256':dependencies,'result':value})
